import type { LessonSource } from "../types";
import { preciseResourceUrl } from "../services/resourceSupport";

/**
 * The one source that says each lesson's fact, for lessons whose seed or note did not name one: the learn card's
 * source chip and the answer sheet's source chip (after a right or a wrong answer) show it. Each was checked against
 * the text of the hadith or ayah it cites: a Quran ayah, a hadith in al-Bukhari or Muslim, or a hadith that
 * al-Albani graded sahih or hasan. A lesson with no single source that says its fact has none here.
 */

function ayah(reference: string, title: string, summary: string): LessonSource {
  const [surah, ayahs] = reference.split(":");
  return {
    id: `quran_${surah}_${ayahs.replace("-", "_")}`,
    site: "Quran.com",
    category: "tafsir",
    title,
    url: preciseResourceUrl("Quran.com", `https://quran.com/${surah}/${ayahs}`, `Quran ${reference}`),
    reference: `Quran ${reference}`,
    from: "The Quran with tafsir on Quran.com",
    grade: "Quran",
    summary
  };
}

// A surah's own page: its name, where it was revealed and how many ayahs it has.
function surah(number: number, title: string, summary: string): LessonSource {
  return {
    id: `quran_surah_${number}`,
    site: "Quran.com",
    category: "tafsir",
    title,
    url: `https://quran.com/${number}`,
    reference: `Quran ${number}`,
    from: "The Quran with tafsir on Quran.com",
    grade: "Quran",
    summary
  };
}

function hadith(collection: string, number: string, reference: string, narrator: string, imam: string, grade: string, title: string, summary: string): LessonSource {
  return {
    id: `hadith_${collection}_${number}`,
    site: "Sunnah.com",
    category: "hadith",
    title,
    url: `https://sunnah.com/${collection}:${number}`,
    reference,
    from: `${narrator}; collected by ${imam}`,
    grade,
    summary
  };
}

// The classical books of the companions' lives, read on Shamela (Arabic): a reference gives the volume and page of the
// printed edition Shamela follows, and the link opens the book. Ibn al-Mundhir's al-Ijma' records what the scholars
// agreed on.
const BOOKS = {
  siyar: { shamela: 10906, name: "Siyar A'lam an-Nubala", from: "Siyar A'lam an-Nubala by adh-Dhahabi (Arabic, on Shamela)" },
  isabah: { shamela: 9767, name: "Al-Isabah", from: "Al-Isabah fi Tamyiz as-Sahabah by Ibn Hajar (Arabic, on Shamela)" },
  tabaqat: { shamela: 1686, name: "Tabaqat Ibn Sa'd", from: "At-Tabaqat al-Kubra by Ibn Sa'd (Arabic, on Shamela)" },
  ijma: { shamela: 12445, name: "Al-Ijma'", from: "Al-Ijma' by Ibn al-Mundhir (Arabic, on Shamela)" }
} as const;

function book(key: keyof typeof BOOKS, volume: number, page: number, title: string, summary: string): LessonSource {
  const { shamela, name, from } = BOOKS[key];
  return {
    id: `book_${key}_${volume}_${page}`,
    site: "Shamela",
    category: key === "ijma" ? "article" : "biography",
    title,
    url: `https://shamela.ws/book/${shamela}`,
    reference: key === "ijma" ? `${name} ${page}` : `${name} ${volume}/${page}`,
    from,
    grade: key === "ijma" ? "Consensus of the scholars" : "Biography",
    summary
  };
}

function islamqa(answer: number, title: string, summary: string, highlight?: string): LessonSource {
  return {
    id: `islamqa_${answer}`,
    site: "IslamQA",
    category: "article",
    title,
    url: `https://islamqa.info/en/answers/${answer}`,
    reference: `IslamQA ${answer}`,
    from: "Islam Question & Answer",
    grade: "Fatwa",
    summary,
    highlight
  };
}

